head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisplayFormatter]<br/>Body Column 정보를 사용하여 특정 Column 의 displayFormatter 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 displayFormatter 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "formatter(필수) 파라미터로 표시되는 Cell 데이터를 변환할 사용자 정의 함수의 이름을 설정합니다.",
        "formatter(필수) 사용자 정의 함수의 파라미터로 Cell 의 실제 데이터가 전달됩니다.",
        "formatter(필수) 사용자 정의 함수의 반환값이 Cell 에 표시되는 데이터로 적용됩니다.",
        "Column 의 displayFormatter 속성이 설정된 경우 displayFormat 속성은 무시됩니다.",
        "Column 의 customFormatter 속성이 설정된 경우 최종 데이터 표시는 customFormatter 로 처리되므로 displayFormatter 결과가 덮어 써질 수 있습니다.",
        "setColumnDisplayFormatter() 메소드로 displayFormatter 속성이 설정되면 모든 Row 가 다시 렌더링됩니다.",
    ]
}



// formatter(필수) 사용자 정의 함수 : Cell 실제 데이터를 받아 '값 + 원' 으로 변환 -> 실데이터 전달 + 반환값 표시 확인용
scwin.fmtWon = function (data) {
    return data + " 원";
};

// formatter(필수) 사용자 정의 함수 (대체) : Cell 실제 데이터를 부등호로 감싸 표시 -> 반환값 적용 확인용
scwin.fmtTag = function (data) {
    return "<" + data + ">";
};

// customFormatter Column(인덱스 3) 용 사용자 함수 : displayFormatter 결과 위에 다시 덮어쓰는지 확인용
scwin.fmtCustom = function (data) {
    return "C:" + data;
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 columnInfo 선택값(0)
    par_columnInfo.setValue("0");
};



// comp 생성 : text/숨김text/displayFormat 설정 number/customFormatter 설정 number Column 구성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스(숨김 포함) - 0:ctext(text) / 1:chide(text, setColumnVisible(1,false) 로 숨김) / 2:cnum(number, displayFormat=#,##0.00 설정) / 3:ccustom(number, customFormatter=fmtCustom 설정). 데이터 Row 3개.\n[절차] columnInfo(인덱스) 와 formatter(함수명) 선택 후 (setColumnDisplayFormatter 실행) -> 해당 Column 모든 Row 셀의 화면 표시값이 사용자 함수 반환값으로 바뀌는지 확인.\n[확인] formatter 함수는 셀 실제 데이터를 인자로 받아 반환값(예: 데이터+원)이 표시됨. displayFormat 설정 Column(2) 은 displayFormat 무시되고 formatter 적용. customFormatter 설정 Column(3) 은 customFormatter(C:..) 가 최종 덮어씀."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chide" name="chide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cnum" name="cnum" dataType="number"></w2:column>';
    strDlt += '<w2:column id="ccustom" name="ccustom" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "ctext": "1234567", "chide": "숨김1", "cnum": "1250",  "ccustom": "2000" },
        { "ctext": "9876543", "chide": "숨김2", "cnum": "30500", "ccustom": "3000" },
        { "ctext": "5550000", "chide": "숨김3", "cnum": "780",   "ccustom": "4000" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text / 숨김 text / displayFormat 설정 number / customFormatter 설정 number)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnDisplayFormatter 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" inputType="text" id="h0" value="0:text"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h1" value="1:숨김"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="h2" value="2:number(displayFormat)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h3" value="3:number(customFormatter)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 0 : text -> setColumnDisplayFormatter(0,"scwin.fmtWon") 시 모든 Row 가 변환 표시
    strTarget += '<w2:column width="150" inputType="text" dataType="text" id="ctext" dataList="ctext"></w2:column>';
    // 1 : text 숨김(setColumnVisible(1,false)) -> 숨김 Column 포함 인덱스 검증용
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="chide" dataList="chide"></w2:column>';
    // 2 : number + displayFormat="#,##0.00" -> setColumnDisplayFormatter 설정 시 displayFormat 무시되고 formatter 적용
    strTarget += '<w2:column width="180" inputType="text" dataType="number" displayFormat="#,##0.00" id="cnum" dataList="cnum"></w2:column>';
    // 3 : number + customFormatter="scwin.fmtCustom" -> setColumnDisplayFormatter 결과를 customFormatter 가 덮어씀
    strTarget += '<w2:column width="*" inputType="text" dataType="number" customFormatter="scwin.fmtCustom" id="ccustom" dataList="ccustom"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(chide, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// [실행] setColumnDisplayFormatter : columnInfo(인덱스) 와 formatter(함수명) 으로 해당 Column 의 displayFormatter 속성을 설정한다.
//  - 설정 후 해당 Column 의 모든 Row 화면 표시값(td.textContent) 을 수집하여 사용자 함수 반환값으로 변환/재렌더되었는지 확인
//  - displayFormat 설정 Column 은 무시, customFormatter 설정 Column 은 customFormatter 로 덮어쓰는지 함께 확인
scwin.btn_setColumnDisplayFormatter_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let formatter = par_formatter.getValue();
    let colID = target1.getColumnID(columnInfo);
    let cnt = dlt_bind.getRowCount();

    // setColumnDisplayFormatter 호출
    target1.setColumnDisplayFormatter(columnInfo, formatter);

    // 적용된 해당 Column 의 모든 Row 화면 표시값 수집 (모든 Row 재렌더 확인)
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
        arr.push(td ? td.textContent.trim() : '');
    }

    let msg = "setColumnDisplayFormatter(" + columnInfo + ", '" + formatter + "') [" + colID + "] -> 모든 Row 화면 표시값 : " + arr.join(', ');

    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
